PREPARE login_stmt FROM 'SELECT id, name FROM users WHERE phone = ? AND password_hash = ?';
SET @phone = '13800000000';
SET @pwd = SHA2('user-input-pass', 256);
EXECUTE login_stmt USING @phone, @pwd;
DEALLOCATE PREPARE login_stmt;

SET @city = '上海';
SET @sql = CONCAT('SELECT id, name FROM users WHERE city = ', QUOTE(@city));
PREPARE q FROM @sql;
EXECUTE q;
DEALLOCATE PREPARE q;
